import{_ as p,a0 as t,w as o,s as h,I as n,x as a,a1 as i,A as l,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const q=JSON.parse('{"title":"如何使用 Bash history 命令 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用 Bash history 命令 | LCTT (202006) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用 Bash history 命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用 Bash history 命令 | LCTT (202006) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202006/20200615 How to use Bash history commands","title":"如何使用 Bash history 命令","tag":"202006","desc":""},"relativePath":"202006/20200615 How to use Bash history commands.md","filePath":"[post].md"}'),d={name:"202006/20200615 How to use Bash history commands.md"};function u(c,s,g,b,k,f){const e=t("Link");return o(),h("div",null,[s[22]||(s[22]=n("h1",{id:"如何使用-bash-history-命令",tabindex:"-1"},[a("如何使用 Bash history 命令 "),n("a",{class:"header-anchor",href:"#如何使用-bash-history-命令","aria-label":"Permalink to “如何使用 Bash history 命令”"},"​")],-1)),s[23]||(s[23]=n("blockquote",null,[n("p",null,"Bash 的 history 命令在它提供的功能数量上超过了所有其他 Linux Shell 历史接口。")],-1)),s[24]||(s[24]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202006/24/101620c0uj0dgg0buo9nib.jpg",alt:""})],-1)),n("p",null,[s[1]||(s[1]=a("Bash 有丰富的历史。也就是说，它是一个古老的的 shell，还有一个更古老的 Shell （Bourne shell）的前辈，但是它还有一个很棒的 ",-1)),s[2]||(s[2]=n("code",null,"history",-1)),s[3]||(s[3]=a(" 命令，它提供的功能数量超过了所有其他 shell 的历史接口。 ",-1)),i(e,{href:"https://opensource.com/resources/what-bash"},{default:l(()=>[...s[0]||(s[0]=[a("Bash",-1)])]),_:1}),s[4]||(s[4]=a(" 版本的 ",-1)),s[5]||(s[5]=n("code",null,"history",-1)),s[6]||(s[6]=a(" 可进行反向搜索、快速调用、重写历史记录等。",-1))]),s[25]||(s[25]=r(`<p><code>history</code> 命令与许多其他命令不同。你可能习惯于将命令作为可执行文件放在常见的系统级位置，例如 <code>/usr/bin</code>、<code>/usr/local/bin</code> 或者 <code>~/bin</code>。 内置的 <code>history</code> 命令不在你的 <code>PATH</code> 中并且没有物理位置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ which history</span></span>
<span class="line"><span></span></span>
<span class="line"><span>which: no history in [PATH]</span></span></code></pre></div><p>相反，<code>history</code> 是 shell 本身的内置函数：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ type history</span></span>
<span class="line"><span>history is a shell builtin</span></span>
<span class="line"><span>$ help history</span></span>
<span class="line"><span>history: history [-c] [-d offset] [n] or</span></span>
<span class="line"><span>history -anrw [filename] or</span></span>
<span class="line"><span>history -ps arg [arg...]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Display or manipulate the history list.</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>出于这个原因，每个 shell 中的历史功能都是独特的，因此你在 Bash 中使用的功能可能无法在 Tcsh 或 Fish 或 Dash 中使用，而在这些 shell 中使用的功能可能也无法在 Bash 中使用。在某些情况下，了解 Bash 可以做什么可能会激发其他 shell 的用户创建有趣的改造来复制 Bash 行为，并且可能会解锁你从未知道的 Bash 功能。</p><h3 id="查看你的-bash-历史" tabindex="-1">查看你的 Bash 历史 <a class="header-anchor" href="#查看你的-bash-历史" aria-label="Permalink to “查看你的 Bash 历史”">​</a></h3><p><code>history</code> 命令最基本、最频繁的用法是查看 shell 会话的历史记录：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;hello&quot;</span></span>
<span class="line"><span>hello</span></span>
<span class="line"><span>$ echo &quot;world&quot;</span></span>
<span class="line"><span>world</span></span>
<span class="line"><span>$ history</span></span>
<span class="line"><span>  1  echo &quot;hello&quot;</span></span>
<span class="line"><span>  2  echo &quot;world&quot;</span></span>
<span class="line"><span>  3  history</span></span></code></pre></div><h3 id="事件指示器" tabindex="-1">事件指示器 <a class="header-anchor" href="#事件指示器" aria-label="Permalink to “事件指示器”">​</a></h3><p><ruby>事件指示器<rt>Event designator</rt></ruby>按事件搜索你的历史记录。在这里，“事件”是指记录在历史中的命令，以换行符划定。换句话说，一行一个事件，以索引号来标记。</p><p>事件指示器大多以感叹号开头，有时也称为 “bang”（<code>!</code>）。</p><p>要从你的历史记录中重新运行命令，请使用感叹号，之后紧跟（之间没有空格）所需命令的索引号。例如，假设第 1 行包含命令 <code>echo &quot;hello&quot;</code>，你想要想再次运行它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ !1</span></span>
<span class="line"><span>echo &quot;hello&quot;</span></span>
<span class="line"><span>hello</span></span></code></pre></div><p>你可以使用相对定位，提供基于你历史中当前位置向后的负数行号。例如，返回到历史中倒数第三个条目：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;foo&quot;</span></span>
<span class="line"><span>foo</span></span>
<span class="line"><span>$ echo &quot;bar&quot;</span></span>
<span class="line"><span>bar</span></span>
<span class="line"><span>$ echo &quot;baz&quot;</span></span>
<span class="line"><span>baz</span></span>
<span class="line"><span>$ !-3</span></span>
<span class="line"><span>echo &quot;foo&quot;</span></span>
<span class="line"><span>foo</span></span></code></pre></div><p>如果只想回去一行，那么可以使用速记 <code>!!</code> 代替 <code>!-1</code>。这节省了按键时间！</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;foo&quot;</span></span>
<span class="line"><span>$ !!</span></span>
<span class="line"><span>echo &quot;foo&quot;</span></span>
<span class="line"><span>foo</span></span></code></pre></div><h3 id="字符串搜索" tabindex="-1">字符串搜索 <a class="header-anchor" href="#字符串搜索" aria-label="Permalink to “字符串搜索”">​</a></h3><p>你也可以对条目搜索特定的字符串，反过来搜索要运行命令。要搜索以指定字符串<em>开始</em>的命令，请使用感叹号，之后紧跟（没有空格）要搜索的字符串：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;foo&quot;</span></span>
<span class="line"><span>$ true</span></span>
<span class="line"><span>$ false</span></span>
<span class="line"><span>$ !echo</span></span>
<span class="line"><span>echo &quot;foo&quot;</span></span>
<span class="line"><span>foo</span></span></code></pre></div><p>你还可以在任意位置（不仅是开头）搜索包含该字符串的命令。为此，请像之前一样使用 <code>!</code> 加上要搜索的字符串，但在字符串的两端都用问号（<code>?</code>）围绕起来。如果你知道该字符串后紧跟一个换行符，那么可以省略最后的问号（就是在按<em>回车</em>之前输入的最后字符）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;foo&quot;</span></span>
<span class="line"><span>$ true</span></span>
<span class="line"><span>$ false</span></span>
<span class="line"><span>$ !?foo?</span></span>
<span class="line"><span>echo &quot;foo&quot;</span></span>
<span class="line"><span>foo</span></span></code></pre></div><h3 id="字符串替换" tabindex="-1">字符串替换 <a class="header-anchor" href="#字符串替换" aria-label="Permalink to “字符串替换”">​</a></h3><p>类似于在行首搜索字符串，你可以搜索字符串并用新字符串替换它，以更改命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;hello&quot;</span></span>
<span class="line"><span>hello</span></span>
<span class="line"><span>$ echo &quot;world&quot;</span></span>
<span class="line"><span>world</span></span>
<span class="line"><span>$ ^hello^foo</span></span>
<span class="line"><span>echo &quot;foo&quot;</span></span>
<span class="line"><span>foo</span></span></code></pre></div><h3 id="让-history-有用" tabindex="-1">让 history 有用 <a class="header-anchor" href="#让-history-有用" aria-label="Permalink to “让 history 有用”">​</a></h3><p>在 Bash 中，<code>history</code> 命令的功能远远超过此处介绍的内容，但这是一个很好的开始, 可以让你习惯使用你的历史记录, 而不是仅仅把它当作一个参考。经常使用 <code>history</code> 命令，并试试无需输入命令即可执行的操作。你可能会感到惊讶！</p><hr>`,28)),n("p",null,[s[8]||(s[8]=a("via: ",-1)),i(e,{href:"https://opensource.com/article/20/6/bash-history-commands"},{default:l(()=>[...s[7]||(s[7]=[a("https://opensource.com/article/20/6/bash-history-commands",-1)])]),_:1})]),n("p",null,[s[13]||(s[13]=a("作者：",-1)),i(e,{href:"https://opensource.com/users/seth"},{default:l(()=>[...s[9]||(s[9]=[a("Seth Kenlon",-1)])]),_:1}),s[14]||(s[14]=a(" 选题：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:l(()=>[...s[10]||(s[10]=[a("lujun9972",-1)])]),_:1}),s[15]||(s[15]=a(" 译者：",-1)),i(e,{href:"https://github.com/geekpi"},{default:l(()=>[...s[11]||(s[11]=[a("geekpi",-1)])]),_:1}),s[16]||(s[16]=a(" 校对：",-1)),i(e,{href:"https://github.com/wxy"},{default:l(()=>[...s[12]||(s[12]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[19]||(s[19]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[17]||(s[17]=[a("LCTT",-1)])]),_:1}),s[20]||(s[20]=a(" 原创编译，",-1)),i(e,{href:"https://linux.cn/"},{default:l(()=>[...s[18]||(s[18]=[a("Linux中国",-1)])]),_:1}),s[21]||(s[21]=a(" 荣誉推出",-1))])])}const C=p(d,[["render",u]]);export{q as __pageData,C as default};
